sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.hotel-hero {
  min-height: 570px;
  width: 100%;
  box-sizing: border-box;
  position: relative;
  display: flex;
  align-items: center;
  padding: 90px 9%;
  overflow: hidden;
  background:
    linear-gradient(90deg, rgba(15, 36, 29, 0.88), rgba(15, 36, 29, 0.48), rgba(15, 36, 29, 0.12)),
    linear-gradient(135deg, #294b40, #78978a 55%, #d4b99a);
  color: #ffffff;
  font-family: Arial, sans-serif;
}

.hero-content {
  max-width: 700px;
  position: relative;
  z-index: 2;
}

.hero-eyebrow {
  display: block;
  color: #e6c79c;
  font-size: 11px;
  font-weight: bold;
  letter-spacing: 4px;
  margin-bottom: 22px;
}

.hero-content h1 {
  font-family: Georgia, serif;
  font-size: clamp(42px, 6vw, 76px);
  line-height: 1.08;
  font-weight: normal;
  margin: 0 0 22px;
  color: #ffffff;
}

.hero-content p {
  max-width: 520px;
  color: rgba(255, 255, 255, 0.88);
  font-size: 16px;
  line-height: 1.8;
  margin: 0 0 32px;
}

.hero-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.hero-button {
  display: inline-block;
  text-decoration: none;
  padding: 15px 27px;
  border-radius: 3px;
  font-size: 13px;
  font-weight: bold;
  transition: all 0.2s ease;
}

.hero-button.primary {
  background: #e6c79c;
  color: #1f3a30;
}

.hero-button.primary:hover {
  background: #d4b07c;
}

.hero-button.secondary {
  border: 1px solid rgba(255,255,255,0.8);
  color: #ffffff;
}

.hero-button.secondary:hover {
  background: rgba(255,255,255,0.15);
}

.hero-scroll {
  position: absolute;
  bottom: 28px;
  left: 9%;
  display: flex;
  align-items: center;
  gap: 12px;
  color: rgba(255,255,255,0.75);
  font-size: 9px;
  letter-spacing: 2px;
}

.hero-scroll span {
  width: 35px;
  height: 1px;
  background: #e6c79c;
}

@media (max-width: 600px) {
  .hotel-hero {
    min-height: 500px;
    padding: 65px 7%;
  }

  .hero-content h1 {
    font-size: 44px;
  }

  .hero-scroll {
    left: 7%;
  }
}
